import java.net.URI;
import java.net.http.*;
import java.nio.file.*;
import java.util.*;
import org.apache.catalina.connector.Connector;
import org.apache.catalina.Context;
import org.apache.catalina.startup.Tomcat;

public class XPagesTest {
    public static void main(String[] args) throws Exception {
        var root=Path.of("").toAbsolutePath();
        Tomcat server=new Tomcat();
        server.setBaseDir(root.resolve("server").toString());
        Connector connector=new Connector();
        connector.setPort(0);
        connector.setProperty("address", "127.0.0.1");
        server.setConnector(connector);
        var context=server.addWebapp("",root.resolve("web").toString());
        context.setParentClassLoader(XPagesTest.class.getClassLoader());
        try {
            server.start();
            var target=URI.create("http://127.0.0.1:"+connector.getLocalPort()+"/index.xhtml");
            var client=HttpClient.newBuilder().connectTimeout(java.time.Duration.ofSeconds(5)).build();
            var response=client.send(HttpRequest.newBuilder(target).GET().build(),HttpResponse.BodyHandlers.ofString());
            System.out.println("HTTP " + response.statusCode());
            System.out.println(response.body());
            if (response.statusCode()!=200) throw new IllegalStateException("Render failed");
        } finally {
            server.stop();
            server.destroy();
        }
    }
}
